-- ============================================================
--  Тема «Непряма мова (Reported Speech)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/reported_speech.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$reported_speech$g0$, $g1$Непряма мова (Reported Speech)$g1$, $g2$Непряма мова: розповідні речення й зсув часів, питання, накази, прохання та пропозиції, вступні дієслова (agree, accuse, suggest…).$g2$, 12, $g3$[{"slug":"rep_statements","title":"Розповідні речення: крок назад у часі","description":"Як змінюються часи, займенники та слова часу й місця, коли переказуємо чиїсь слова, і коли часи не змінюються."},{"slug":"rep_questions","title":"Питання в непрямій мові: ask, wonder, want to know","description":"Порядок слів як у розповіді, if / whether для питань «так чи ні» та питальне слово для решти."},{"slug":"rep_commands","title":"Накази, прохання, пропозиції","description":"Ask, tell, order + кого + to do, а також suggest + -ing чи that-клауза."},{"slug":"rep_verbs","title":"Вступні дієслова: agree, accuse, suggest…","description":"Дієслова, що передають не лише слова, а й намір: після них інфінітив, -ing або that-клауза."},{"slug":"rep_mix","title":"Змішана практика: усі види непрямої мови","description":"Розповіді, питання, накази та пропозиції разом. Окремої теорії тут немає.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$th_1$g4$, $g5$Крок назад: як змінюються часи$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Зсув часів","kicker":"Базове розуміння","lead":"Коли вступне дієслово у минулому (<i>said, told</i>), час у переказі зсувається на крок назад. Те саме робимо, якщо пересказ застарів або ми вважаємо слова неправдою.","tiles":[{"role":"пряма мова","label":"'I need a new car.'","tone":"colour"},{"role":"непряма мова","label":"he needed a new car","tone":"noun"}],"legend":[{"tone":"colour","label":"Пряма мова: слова так, як їх сказали"},{"tone":"noun","label":"Непряма мова: пересказ, час зсунуто назад"}],"examples":[{"text":"present simple → <b>past simple</b>: 'I need a new car,' Greg said. → Greg said (that) he <b>needed</b> a new car.","plain":"Greg said he needed a new car.","note":"present simple"},{"text":"present continuous → <b>past continuous</b>: 'He's sleeping,' she said. → She said (that) he <b>was sleeping</b>.","plain":"She said he was sleeping.","note":"continuous"},{"text":"present perfect → <b>past perfect</b>: 'I've seen this film,' he said. → He said (that) he <b>had</b> already <b>seen</b> the film.","plain":"He said he had already seen the film.","note":"present perfect"},{"text":"past simple → <b>past simple / past perfect</b>: 'I got up late,' Tonia said. → Tonia said (that) she <b>(had) got up</b> late.","plain":"Tonia said she had got up late.","note":"past simple"},{"text":"past continuous → <b>past cont. / past perfect cont.</b>: 'I was working at four,' Tim said. → Tim said (that) he <b>was working / had been working</b> at four o'clock.","plain":"Tim said he had been working at four o'clock.","note":"past continuous"},{"text":"future will → <b>would</b>: 'I'll call you tomorrow,' Rea said. → Rea said (that) she <b>would call</b> me the following day.","plain":"Rea said she would call me the following day.","note":"will → would"}],"note":"<b>Past Perfect</b> і <b>Past Perfect Continuous</b> у переказі не змінюються: далі назад іти нікуди."}$g8$::jsonb, null, 0, $g9$rep_statements$g9$
from public.topics where slug = $g10$reported_speech$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$th_2$g11$, $g12$Слова часу, місця й this / these$g12$, $g13$elementary$g13$, $g14$pairs$g14$, $g15${"step":"Слова навколо","kicker":"Що ще змінюється","lead":"Разом із часами змінюються слова, прив'язані до моменту мовлення: вказівники часу, місця й this / these.","groups":[{"title":"Час","note":"пряма → непряма","items":[["now","then / at that time / immediately"],["today, tonight","that day, that night"],["yesterday","the day before / the previous day"],["tomorrow","the next day / the following day"],["this week","that week"],["last week","the week before / the previous week"],["next week","the week after / the following week"],["two days ago","two days before"]]},{"title":"Місце й рух","note":"пряма → непряма","items":[["here","there"],["come","go"]]},{"title":"This / these / that / those","note":"залежить від слова після них","items":[["this week, these days","that week, those days"],["this + іменник","the + іменник"],["this / that без іменника","it / they / them"]]}],"notes":["<b>This film is boring</b> → <i>Claire told me (that) <b>the</b> film was boring.</i> This з іменником стає <b>the</b>.","<b>This is an unusual situation</b> → <i>Dad said (that) <b>it</b> was an unusual situation.</i> Без іменника this стає <b>it</b> або <b>they / them</b>."]}$g15$::jsonb, null, 1, $g16$rep_statements$g16$
from public.topics where slug = $g17$reported_speech$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$th_3$g18$, $g19$Модальні дієслова в непрямій мові$g19$, $g20$intermediate$g20$, $g21$cases$g21$, $g22${"step":"Модальні","kicker":"Одні змінюються, інші ні","lead":"Деякі модальні дієслова змінюються разом із часами, інші лишаються без змін.","cards":[{"icon":"→","title":"will → would","text":"Майбутнє у минулому.","example":"'One day I'll be able to afford a car.' → He said one day he <b>would</b> be able to afford a car.","examplePlain":"He said one day he would be able to afford a car."},{"icon":"c","title":"can → could (would be able to)","text":"Із вказівкою на майбутнє — could / would be able to.","example":"'I can speak French.' → He said he <b>could</b> speak French.","examplePlain":"He said he could speak French."},{"icon":"m","title":"may → might","text":"Можливість.","example":"'I may call you.' → He said he <b>might</b> call us.","examplePlain":"He said he might call us."},{"icon":"sh","title":"shall → should / offer","text":"Прохання поради → should. Пропозиція → offered to.","example":"'When shall I come?' → He asked when he <b>should</b> come. / 'Shall I help you?' → He <b>offered to help</b>.","examplePlain":"He asked when he should come. He offered to help."},{"icon":"!","title":"must → must / had to","text":"Зобов'язання: можна лишити must або обрати had to.","example":"'You must finish this.' → He said I <b>must / had to</b> finish it.","examplePlain":"He said I must finish it. He said I had to finish it."},{"icon":"n","title":"needn't → needn't / didn't need to / didn't have to","text":"Відсутність необхідності.","example":"'You needn't pay in cash.' → He said I <b>needn't / didn't need to / didn't have to</b> pay in cash.","examplePlain":"He said I needn't pay in cash."}],"axis":{"title":"Без змін","points":[{"label":"завжди","text":"<b>would, could, might, should, ought, had better, used to, mustn't</b>"},{"label":"must","text":"<b>logical assumption</b> теж без змін"}],"note":"<i>'You must be tired,' Paul told Susan.</i> → <i>Paul told Susan (that) she <b>must</b> be tired.</i> (висновок, а не обов'язок)"}}$g22$::jsonb, null, 2, $g23$rep_statements$g23$
from public.topics where slug = $g24$reported_speech$g24$
