  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$th_4$g25$, $g26$Коли часи не змінюються$g26$, $g27$intermediate$g27$, $g28$cases$g28$, $g29${"step":"Без зсуву","kicker":"Винятки з правила","lead":"Є кілька ситуацій, де зсуву часів не буде. Їх треба розрізняти, бо вправи на це часто побудовано.","cards":[{"icon":"1","title":"Вступне дієслово в теперішньому","text":"<b>Present, future, present perfect</b>: Mum says, he has said, she will say. Передаємо повідомлення, зміст листа чи статті, чи те, що хтось повторює часто.","example":"Mum <b>says</b>, 'Dinner is ready.' → Mum says dinner <b>is</b> ready.","examplePlain":"Mum says dinner is ready."},{"icon":"2","title":"Up-to-date reporting","text":"Переказ того, що ще актуальне: речі, які досі правдиві чи нещодавні.","example":"'I'm lost,' the boy said. → The boy said he <b>is</b> lost.","examplePlain":"The boy said he is lost."},{"icon":"3","title":"Загальна істина","text":"Закон природи чи факт, що не змінюється.","example":"'Paris is the capital of France.' → The teacher said Paris <b>is / was</b> the capital of France.","examplePlain":"The teacher said Paris is the capital of France."},{"icon":"4","title":"Past Perfect","text":"Не змінюється ніколи.","example":"'I had already left.' → He said he <b>had</b> already left.","examplePlain":"He said he had already left."},{"icon":"5","title":"Умовні речення типу 2 і 3","text":"Часи в обох частинах залишаються тими самими.","example":"'If I had more time, I would take up a hobby.' → Eric said if he <b>had</b> more time, he <b>would</b> take up a hobby.","examplePlain":"Eric said if he had more time, he would take up a hobby."},{"icon":"6","title":"Тип 1: Present → Past, will → would","text":"Умови типу 1 зсуваються: present simple → past simple, will → would.","example":"'If you ask Liz, she'll help you.' → He said if I <b>asked</b> Liz, she <b>would</b> help me.","examplePlain":"He said if I asked Liz, she would help me."}]}$g29$::jsonb, null, 3, $g30$rep_statements$g30$
