insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$th_5$g32$, $g33$Стоп-калька: said, told і зсув часів$g33$, $g34$elementary$g34$, $g35$traps$g35$, $g36${"step":"Стоп-калька 1","kicker":"Захист від рідної мови","lead":"Українське «сказав, що…» не показує, ні кому сказали, ні в який час. В англійській це критично.","items":[{"title":"«Вона сказала мені, що втомилась»","bad":"She said me that she was tired.","good":"She <b>told me</b> (that) she was tired. / She <b>said</b> (that) she was tired.","goodPlain":"She told me she was tired. She said she was tired.","rule":"<i>Tell</i> завжди з особою (told me), <i>say</i> — без особи. Say to me — теж можливо, але не <s>said me</s>."},{"title":"«Мама сказала, що буде вдома завтра»","bad":"Mum said she will be home tomorrow.","good":"Mum said she <b>would</b> be home <b>the next day</b>.","goodPlain":"Mum said she would be home the next day.","rule":"Після said (минуле): will → would, tomorrow → the next day."},{"title":"«Вона сказала, що приїхала вчора»","bad":"She said she arrived yesterday.","good":"She said she <b>had arrived the day before</b>.","goodPlain":"She said she had arrived the day before.","rule":"Past simple → past perfect, yesterday → the day before."},{"title":"«Він сказав, що я можу піти»","bad":"He said I can go.","good":"He said I <b>could</b> go.","goodPlain":"He said I could go.","rule":"Can → could після вступного дієслова в минулому."},{"title":"«Я сказав їй, що тут красиво»","bad":"I told her it was beautiful here.","good":"I told her it was beautiful <b>there</b>.","goodPlain":"I told her it was beautiful there.","rule":"Here → there, this → that / the."},{"title":"«Він сказав, що подзвонить мені»","bad":"He said that I'll call.","good":"He said that <b>he</b> would call.","goodPlain":"He said that he would call.","rule":"Займенники теж змінюються за змістом: I → he."}]}$g36$::jsonb, null, 4, $g37$rep_statements$g37$
from public.topics where slug = $g38$reported_speech$g38$
