insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$th_6$g39$, $g40$Непрямі питання: порядок слів як у розповіді$g40$, $g41$elementary$g41$, $g42$formula$g42$, $g43${"step":"Питання","kicker":"Базове розуміння","lead":"У непрямому питанні немає ні знака питання, ні допоміжного do / does / did. Порядок слів прямий: підмет перед дієсловом.","tiles":[{"role":"вступ","label":"asked (me)","tone":"colour"},{"role":"питальне слово або if","label":"what / if / whether","tone":"noun"},{"role":"прямий порядок","label":"subject + verb","tone":"neutral"}],"legend":[{"tone":"colour","label":"Вступні дієслова: ask, inquire, wonder, want to know"},{"tone":"noun","label":"Wh-слова (who, where, how old…) лишаються, для «так чи ні» — if або whether"}],"examples":[{"text":"'<b>What</b> did you make for dinner yesterday?' → Bob asked me <b>what I had made</b> for dinner the day before.","plain":"Bob asked me what I had made for dinner the day before.","note":"wh-питання"},{"text":"'<b>Why</b> do you want to leave your job?' → Pam asked me <b>why I wanted</b> to leave my job.","plain":"Pam asked me why I wanted to leave my job.","note":"wh-питання"},{"text":"'<b>Do</b> you like rock music?' → He asked us <b>if / whether we liked</b> rock music.","plain":"He asked us if we liked rock music.","note":"так чи ні"},{"text":"'<b>Can</b> you ride a motorcycle?' → Ben asked David <b>if / whether he could ride</b> a motorcycle.","plain":"Ben asked David if he could ride a motorcycle.","note":"модальне"}],"note":"Слова <i>please, well, oh</i> у переказі опускаємо. Часи й слова часу змінюються так само, як у розповідних реченнях."}$g43$::jsonb, null, 5, $g44$rep_questions$g44$
from public.topics where slug = $g45$reported_speech$g45$
