insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$th_7$g46$, $g47$Стоп-калька: питання в непрямій мові$g47$, $g48$elementary$g48$, $g49$traps$g49$, $g50${"step":"Стоп-калька 2","kicker":"Захист від рідної мови","lead":"Українська дозволяє переставляти слова, а англійська в непрямому питанні — ні.","items":[{"title":"«Він запитав, де я живу»","bad":"He asked me where did I live.","good":"He asked me where <b>I lived</b>.","goodPlain":"He asked me where I lived.","rule":"У непрямому питанні немає do / did, а порядок слів прямий."},{"title":"«Вона запитала, чи я люблю каву»","bad":"She asked me do I like coffee.","good":"She asked me <b>if I liked</b> coffee.","goodPlain":"She asked me if I liked coffee.","rule":"Питання «так чи ні» вводить if або whether."},{"title":"«Він запитав, куди я йду»","bad":"He asked where was I going.","good":"He asked where <b>I was going</b>.","goodPlain":"He asked where I was going.","rule":"Підмет перед дієсловом."},{"title":"«Вона запитала, хто там»","bad":"She asked who is there?","good":"She asked who <b>was</b> there.","goodPlain":"She asked who was there.","rule":"Без знака питання, і з зсувом часу: is → was."},{"title":"«Мама запитала, коли я приїду»","bad":"Mum asked me when will I come.","good":"Mum asked me when <b>I would come</b>.","goodPlain":"Mum asked me when I would come.","rule":"Will → would, і порядок прямий."},{"title":"«Він запитав, чи можна взяти книжку»","bad":"He asked that he can take the book.","good":"He asked <b>if he could</b> take the book.","goodPlain":"He asked if he could take the book.","rule":"Після ask замість that — if або whether, і can → could."}]}$g50$::jsonb, null, 6, $g51$rep_questions$g51$
