insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$th_8$g53$, $g54$Накази, прохання, пропозиції$g54$, $g55$elementary$g55$, $g56$cases$g56$, $g57${"step":"Команди й поради","kicker":"Не речення, а дія","lead":"Накази й прохання передаємо інфінітивом, а пропозиції — формою на -ing або that-клаузою.","cards":[{"icon":"!","title":"Наказ: told / ordered + кого + to V","text":"Прямий наказ.","example":"'Stop the car!' → The policeman <b>ordered him to stop</b> the car.","examplePlain":"The policeman ordered him to stop the car."},{"icon":"?","title":"Прохання: asked + кого + to V","text":"Ввічливе звернення (please, can you, will you).","example":"'Will you hold this bag for me?' → Laura <b>asked Helen to hold</b> the bag for her.","examplePlain":"Laura asked Helen to hold the bag for her."},{"icon":"✗","title":"Заборона: not to V","text":"Not стоїть перед інфінітивом.","example":"'Please, don't tell anyone.' → Lorna <b>asked them not to tell</b> anyone.","examplePlain":"Lorna asked them not to tell anyone."},{"icon":"+","title":"Інструкція: told + кого + to V","text":"Порада чи інструкція.","example":"'Put all the ingredients in a bowl.' → She <b>told me to put</b> all the ingredients in a bowl.","examplePlain":"She told me to put all the ingredients in a bowl."},{"icon":"S","title":"Пропозиція: suggested + -ing","text":"Let's, Shall we, How about + -ing → suggested + -ing.","example":"'How about going to the cinema?' → I <b>suggested going</b> to the cinema.","examplePlain":"I suggested going to the cinema."},{"icon":"T","title":"Пропозиція: suggested + that + should","text":"Те саме, але з підметом.","example":"'Let's call the expert.' → Jim suggested <b>(that) we (should) call</b> the expert.","examplePlain":"Jim suggested that we should call the expert."}]}$g57$::jsonb, null, 7, $g58$rep_commands$g58$
