insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$th_9$g60$, $g61$Стоп-калька: накази й пропозиції$g61$, $g62$intermediate$g62$, $g63$traps$g63$, $g64${"step":"Стоп-калька 3","kicker":"Ще шість пасток","lead":"Український «просив, щоб» і «запропонував піти» часто переносять дослівно.","items":[{"title":"«Він сказав мені не ходити туди»","bad":"He told me don't go there.","good":"He told me <b>not to go</b> there.","goodPlain":"He told me not to go there.","rule":"Наказ у непрямій мові — інфінітив, не пряма форма."},{"title":"«Вона запропонувала піти»","bad":"She suggested to go.","good":"She suggested <b>going</b>.","goodPlain":"She suggested going.","rule":"Suggest + -ing, не to + інфінітив."},{"title":"«Він запропонував мені піти»","bad":"He suggested me to go.","good":"He suggested <b>that I (should) go</b>.","goodPlain":"He suggested that I should go.","rule":"Suggest не має конструкції «кого + to V». Є: suggested + -ing або suggested that + clause."},{"title":"«Вона попросила не шуміти»","bad":"She asked don't make noise.","good":"She asked <b>us not to make</b> noise.","goodPlain":"She asked us not to make noise.","rule":"Asked + кого + (not) to V."},{"title":"«Він наказав відчинити двері»","bad":"He ordered to open the door.","good":"He ordered <b>me to open</b> the door.","goodPlain":"He ordered me to open the door.","rule":"Order / tell / ask потребують особи: кого."},{"title":"«Вона попросила, щоб я допоміг»","bad":"She asked that I help her.","good":"She asked <b>me to help</b> her.","goodPlain":"She asked me to help her.","rule":"Після ask — кого + to V, а не that-клауза."}]}$g64$::jsonb, null, 8, $g65$rep_commands$g65$
