insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g67$th_10$g67$, $g68$Вступні дієслова та їх структури$g68$, $g69$intermediate$g69$, $g70$pairs$g70$, $g71${"step":"Вступні дієслова","kicker":"Що стоїть після дієслова","lead":"Вступні дієслова передають і слова, і намір мовця. Від дієслова залежить, що стоїть після нього: інфінітив, особа + інфінітив, -ing чи that-клауза.","groups":[{"title":"+ to-інфінітив","note":"agree, offer, refuse…","items":[["agree","He agreed to lend me the money."],["claim *","He claimed to have seen the robbers."],["demand","He demanded to be given the money."],["offer","He offered to help me."],["promise *","He promised to return the book."],["refuse","He refused to call her."],["threaten *","He threatened to punish her."]]},{"title":"+ особа + to-інфінітив","note":"advise, ask, warn…","items":[["advise","He advised me to eat more fruit."],["allow","He allowed me to go to the party."],["ask","He asked me to do him a favour."],["beg","He begged them not to hurt him."],["command","He commanded them to put their hands up."],["forbid","He forbade me to stay out late."],["invite","He invited me to go to his wedding."],["order","He ordered me to go to my room."],["remind *","He reminded me to buy some milk."],["warn","He warned me not to touch the iron."]]},{"title":"+ форма на -ing","note":"accuse, deny, suggest…","items":[["accuse sb of","He accused her of committing the crime."],["admit (to) *","He admitted (to) giving away my secret."],["apologise for","He apologised for being late."],["boast about / of *","He boasted about being the best student."],["complain (to sb) of *","He complained of having noisy neighbours."],["deny *","He denied using my computer."],["insist on *","He insisted on me / my finishing by Friday."],["suggest *","He suggested going out to dinner."]]},{"title":"+ that-клауза / how","note":"explain, inform, exclaim","items":[["explain","She explained that she didn't like him because he was rude."],["explain to sb how","He explained to us how it worked."],["inform sb","He informed us that the results would come out the next day."],["exclaim / remark","He exclaimed that it was a glorious day."]]}],"notes":["Дієслова із зірочкою (<b>*</b>) можуть мати й that-клаузу: <i>He claimed <b>that</b> he had won a prize.</i>"]}$g71$::jsonb, null, 9, $g72$rep_verbs$g72$
