insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g74$th_11$g74$, $g75$Дієслова зі зірочкою: ще й that-клауза$g75$, $g76$advanced$g76$, $g77$formula$g77$, $g78${"step":"Два варіанти","kicker":"Для просунутих","lead":"Дієслова claim, promise, threaten, remind, admit, boast, complain, deny, insist, suggest мають два способи: інфінітив / -ing або that-клауза.","tiles":[{"role":"дієслово","label":"claim / promise…","tone":"colour"},{"role":"структура 1","label":"to V / -ing","tone":"noun"},{"role":"структура 2","label":"(that) + clause","tone":"neutral"}],"legend":[{"tone":"noun","label":"Коротка форма"},{"tone":"neutral","label":"Повна форма з підметом"}],"examples":[{"text":"He <b>claimed that</b> he had won a prize.","plain":"He claimed that he had won a prize.","note":"claim"},{"text":"He <b>promised that</b> he would call.","plain":"He promised that he would call.","note":"promise"},{"text":"He <b>threatened that</b> he would leave.","plain":"He threatened that he would leave.","note":"threaten"},{"text":"He <b>reminded me that</b> I had a meeting that afternoon.","plain":"He reminded me that I had a meeting that afternoon.","note":"remind"},{"text":"He <b>admitted that</b> he was wrong.","plain":"He admitted that he was wrong.","note":"admit"},{"text":"He <b>boasted that</b> he was very rich.","plain":"He boasted that he was very rich.","note":"boast"},{"text":"He <b>complained that</b> he didn't earn enough money.","plain":"He complained that he didn't earn enough money.","note":"complain"},{"text":"He <b>denied that</b> he had taken the money.","plain":"He denied that he had taken the money.","note":"deny"},{"text":"He <b>insisted that</b> I (should) work on Saturday.","plain":"He insisted that I should work on Saturday.","note":"insist"},{"text":"He <b>suggested that</b> we (should) take out a loan.","plain":"He suggested that we should take out a loan.","note":"suggest"}],"note":"Після <b>suggest</b> і <b>insist</b> у that-клаузі часто стоїть <b>should</b> або чиста форма дієслова: <i>suggested (that) we should take</i>."}$g78$::jsonb, null, 10, $g79$rep_verbs$g79$
