insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g81$th_12$g81$, $g82$Стоп-калька: вступні дієслова$g82$, $g83$intermediate$g83$, $g84$traps$g84$, $g85${"step":"Стоп-калька 4","kicker":"Захист від рідної мови","lead":"Українські «вибачився, що…» і «пояснив мені» часто тягнуть за собою англійські помилки.","items":[{"title":"«Він вибачився, що запізнився»","bad":"He apologised that he was late.","good":"He apologised <b>for being</b> late.","goodPlain":"He apologised for being late.","rule":"Apologise for + -ing. That-клауза не вживається."},{"title":"«Вона запропонувала мені піти»","bad":"She suggested me to go.","good":"She suggested <b>that I (should) go</b>.","goodPlain":"She suggested that I should go.","rule":"Suggest не має кого + to V."},{"title":"«Він пояснив мені, як це працює»","bad":"He explained me how it worked.","good":"He explained <b>to me</b> how it worked.","goodPlain":"He explained to me how it worked.","rule":"Explain + to sb: без прийменника to особа не вживається."},{"title":"«Він відмовився допомогти»","bad":"He refused helping me.","good":"He refused <b>to help</b> me.","goodPlain":"He refused to help me.","rule":"Refuse + to-інфінітив."},{"title":"«Вона звинуватила його в крадіжці»","bad":"She accused him to steal the wallet.","good":"She accused him <b>of stealing</b> the wallet.","goodPlain":"She accused him of stealing the wallet.","rule":"Accuse sb of + -ing."},{"title":"«Мама нагадала мені, що в мене зустріч»","bad":"Mum reminded that I had a meeting.","good":"Mum reminded <b>me</b> that I had a meeting.","goodPlain":"Mum reminded me that I had a meeting.","rule":"Remind завжди з особою."}]}$g85$::jsonb, null, 11, $g86$rep_verbs$g86$
