  ($g88$rep_ex8_1$g88$, $g89$order$g89$, $g90$intermediate$g90$, $g91${"id":"rep_ex8_1","level":"intermediate","group":8,"gord":8,"no":1,"instruction":"Turn the following into reported questions.","prefix":"He asked me","scrambled":["my","was","what","name"],"answer":"what my name was","hint":"Wh-питання: питальне слово + прямий порядок (my name was). Is → was."}$g91$, 0, $g92$rep_questions$g92$),
  ($g93$rep_ex8_2$g93$, $g94$order$g94$, $g95$intermediate$g95$, $g96${"id":"rep_ex8_2","level":"intermediate","group":8,"gord":8,"no":2,"instruction":"Turn the following into reported questions.","prefix":"Uncle Bill asked us","scrambled":["were","where","parents","our"],"answer":"where our parents were","hint":"Where + прямий порядок: our parents were. Are → were."}$g96$, 1, $g97$rep_questions$g97$),
  ($g98$rep_ex8_4$g98$, $g99$order$g99$, $g100$intermediate$g100$, $g101${"id":"rep_ex8_4","level":"intermediate","group":8,"gord":8,"no":4,"instruction":"Turn the following into reported questions.","prefix":"Mum asked me","scrambled":["what","be","home","I","would","time"],"answer":"what time I would be home","hint":"Wh-питання: what time + I would be. Will → would."}$g101$, 2, $g102$rep_questions$g102$),
  ($g103$rep_ex8_6$g103$, $g104$order$g104$, $g105$intermediate$g105$, $g106${"id":"rep_ex8_6","level":"intermediate","group":8,"gord":8,"no":6,"instruction":"Turn the following into reported questions.","prefix":"David asked Janet","scrambled":["the","had","door","at","been","who"],"answer":"who had been at the door","altAnswer":"who was at the door","hint":"Who + had been: was → had been; порядок слів прямий."}$g106$, 3, $g107$rep_questions$g107$),
  ($g108$rep_ex8_7$g108$, $g109$order$g109$, $g110$intermediate$g110$, $g111${"id":"rep_ex8_7","level":"intermediate","group":8,"gord":8,"no":7,"instruction":"Turn the following into reported questions.","prefix":"They asked us","scrambled":["office","post","where","the","was"],"answer":"where the post office was","hint":"Where + прямий порядок: the post office was."}$g111$, 4, $g112$rep_questions$g112$),
  ($g113$rep_ex8_8$g113$, $g114$order$g114$, $g115$intermediate$g115$, $g116${"id":"rep_ex8_8","level":"intermediate","group":8,"gord":8,"no":8,"instruction":"Turn the following into reported questions.","prefix":"Meg asked me","scrambled":["would","do","homework","I","when","my"],"answer":"when I would do my homework","hint":"When + I would do: will → would, прямий порядок."}$g116$, 5, $g117$rep_questions$g117$),
  ($g118$rep_ex8_12$g118$, $g119$order$g119$, $g120$intermediate$g120$, $g121${"id":"rep_ex8_12","level":"intermediate","group":8,"gord":8,"no":12,"instruction":"Turn the following into reported questions.","prefix":"She asked him","scrambled":["where","his","was","jacket"],"answer":"where his jacket was","hint":"Where + прямий порядок: his jacket was; your → his."}$g121$, 6, $g122$rep_questions$g122$),
  ($g123$rep_ex9_2$g123$, $g124$order$g124$, $g125$intermediate$g125$, $g126${"id":"rep_ex9_2","level":"intermediate","group":9,"gord":9,"no":2,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["his","the","best","was","what","job","of","part"],"answer":"what the best part of his job was","hint":"Wh-питання: the best part of his job was (your → his; is → was)."}$g126$, 7, $g127$rep_questions$g127$),
  ($g128$rep_ex9_3$g128$, $g129$order$g129$, $g130$intermediate$g130$, $g131${"id":"rep_ex9_3","level":"intermediate","group":9,"gord":9,"no":3,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["acting","about","what","difficult","found","he"],"answer":"what he found difficult about acting","hint":"What + he found: do you find → he found (без did)."}$g131$, 8, $g132$rep_questions$g132$),
  ($g133$rep_ex9_4$g133$, $g134$order$g134$, $g135$intermediate$g135$, $g136${"id":"rep_ex9_4","level":"intermediate","group":9,"gord":9,"no":4,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["films","starred","had","he","in","many","how"],"answer":"how many films he had starred in","hint":"Present perfect → past perfect: how many films he had starred in."}$g136$, 9, $g137$rep_questions$g137$),
  ($g138$rep_ex9_5$g138$, $g139$order$g139$, $g140$intermediate$g140$, $g141${"id":"rep_ex9_5","level":"intermediate","group":9,"gord":9,"no":5,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["film","favourite","his","what","was"],"answer":"what his favourite film was","hint":"What + прямий порядок: his favourite film was."}$g141$, 10, $g142$rep_questions$g142$),
  ($g143$rep_ex9_7$g143$, $g144$order$g144$, $g145$intermediate$g145$, $g146${"id":"rep_ex9_7","level":"intermediate","group":9,"gord":9,"no":7,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["would","where","a","most","he","to","like","film","make"],"answer":"where he would most like to make a film","hint":"Would не змінюється: where he would most like to make a film."}$g146$, 11, $g147$rep_questions$g147$),
  ($g148$rep_ex9_9$g148$, $g149$order$g149$, $g150$intermediate$g150$, $g151${"id":"rep_ex9_9","level":"intermediate","group":9,"gord":9,"no":9,"instruction":"Yesterday, Simon interviewed a famous actor. He asked him the following questions. Turn them into reported questions.","prefix":"Simon asked him","scrambled":["his","plans","what","future","were","for","the"],"answer":"what his plans for the future were","hint":"What + прямий порядок: his plans for the future were; are → were."}$g151$, 12, $g152$rep_questions$g152$),
  ($g153$rep_ex2_1$g153$, $g154$gap$g154$, $g155$elementary$g155$, $g156${"id":"rep_ex2_1","level":"elementary","group":2,"gord":2,"no":1,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Sarah: 'I've made lots of friends.' → Sarah told her ______.","answers":["she had made lots of friends","that she had made lots of friends"],"explanation":"Present perfect → past perfect: she had made."}$g156$, 0, $g157$rep_statements$g157$),
  ($g158$rep_ex2_2$g158$, $g159$gap$g159$, $g160$elementary$g160$, $g161${"id":"rep_ex2_2","level":"elementary","group":2,"gord":2,"no":2,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Tina: 'The library is huge.' → Tina told her ______.","answers":["the library was huge","that the library was huge"],"explanation":"Present simple → past simple: is → was."}$g161$, 1, $g162$rep_statements$g162$),
  ($g163$rep_ex2_3$g163$, $g164$gap$g164$, $g165$elementary$g165$, $g166${"id":"rep_ex2_3","level":"elementary","group":2,"gord":2,"no":3,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Paul: 'I'm learning lots of interesting things.' → Paul told her ______.","answers":["he was learning lots of interesting things","that he was learning lots of interesting things"],"explanation":"Present continuous → past continuous; I → he."}$g166$, 2, $g167$rep_statements$g167$),
  ($g168$rep_ex2_4$g168$, $g169$gap$g169$, $g170$elementary$g170$, $g171${"id":"rep_ex2_4","level":"elementary","group":2,"gord":2,"no":4,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Simon: 'The teachers are very friendly.' → Simon told her ______.","answers":["the teachers were very friendly","that the teachers were very friendly"],"explanation":"Present simple → past simple: are → were."}$g171$, 3, $g172$rep_statements$g172$),
  ($g173$rep_ex2_5$g173$, $g174$gap$g174$, $g175$elementary$g175$, $g176${"id":"rep_ex2_5","level":"elementary","group":2,"gord":2,"no":5,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Elaine: 'I will always remember my time here.' → Elaine told her ______.","answers":["she would always remember her time there","that she would always remember her time there"],"explanation":"will → would; my → her; here → there."}$g176$, 4, $g177$rep_statements$g177$),
  ($g178$rep_ex2_6$g178$, $g179$gap$g179$, $g180$elementary$g180$, $g181${"id":"rep_ex2_6","level":"elementary","group":2,"gord":2,"no":6,"instruction":"Ruth met lots of students when she went to visit a university last month. Read their words, then report what they said.","prompt":"Roger: 'I'm taking my final exams next month.' → Roger told her ______.","answers":["he was taking his final exams the following month","that he was taking his final exams the following month","he was taking his final exams the next month","that he was taking his final exams the next month","he was taking his final exams the month after","that he was taking his final exams the month after"],"explanation":"Present continuous → past continuous; next month → the following month."}$g181$, 5, $g182$rep_statements$g182$),
  ($g183$rep_ex3_1$g183$, $g184$gap$g184$, $g185$elementary$g185$, $g186${"id":"rep_ex3_1","level":"elementary","group":3,"gord":3,"no":1,"instruction":"Turn the following sentences into reported speech.","prompt":"Robert said, 'This film is very funny.' → Robert said ______.","answers":["the film was very funny","that the film was very funny"],"explanation":"Is → was; this + іменник → the."}$g186$, 6, $g187$rep_statements$g187$),
  ($g188$rep_ex3_2$g188$, $g189$gap$g189$, $g190$elementary$g190$, $g191${"id":"rep_ex3_2","level":"elementary","group":3,"gord":3,"no":2,"instruction":"Turn the following sentences into reported speech.","prompt":"'I'm starting a new job next week,' she said. → She said ______.","answers":["she was starting a new job the following week","that she was starting a new job the following week","she was starting a new job the next week","that she was starting a new job the next week","she was starting a new job the week after","that she was starting a new job the week after"],"explanation":"Present continuous → past continuous; next week → the following week."}$g191$, 7, $g192$rep_statements$g192$),
  ($g193$rep_ex3_3$g193$, $g194$gap$g194$, $g195$elementary$g195$, $g196${"id":"rep_ex3_3","level":"elementary","group":3,"gord":3,"no":3,"instruction":"Turn the following sentences into reported speech.","prompt":"'I got my exam results last week,' he told them. → He told them ______.","answers":["he had got his exam results the week before","that he had got his exam results the week before","he had got his exam results the previous week","that he had got his exam results the previous week"],"explanation":"Past simple → past perfect; last week → the week before."}$g196$, 8, $g197$rep_statements$g197$),
  ($g198$rep_ex3_4$g198$, $g199$gap$g199$, $g200$elementary$g200$, $g201${"id":"rep_ex3_4","level":"elementary","group":3,"gord":3,"no":4,"instruction":"Turn the following sentences into reported speech.","prompt":"'I can't afford to buy this dress,' said Sally. → Sally said ______.","answers":["she couldn't afford to buy that dress","that she couldn't afford to buy that dress","she couldn't afford to buy the dress","that she couldn't afford to buy the dress","she could not afford to buy that dress","that she could not afford to buy that dress","she could not afford to buy the dress","that she could not afford to buy the dress"],"explanation":"Can't → couldn't; this + іменник → that / the."}$g201$, 9, $g202$rep_statements$g202$),
  ($g203$rep_ex3_5$g203$, $g204$gap$g204$, $g205$elementary$g205$, $g206${"id":"rep_ex3_5","level":"elementary","group":3,"gord":3,"no":5,"instruction":"Turn the following sentences into reported speech.","prompt":"'I would buy a car if I had enough money,' he said to her. → He told her ______.","answers":["he would buy a car if he had enough money","that he would buy a car if he had enough money"],"explanation":"Тип 2 не змінюється, змінюється лише займенник I → he."}$g206$, 10, $g207$rep_statements$g207$),
  ($g208$rep_ex3_6$g208$, $g209$gap$g209$, $g210$elementary$g210$, $g211${"id":"rep_ex3_6","level":"elementary","group":3,"gord":3,"no":6,"instruction":"Turn the following sentences into reported speech.","prompt":"Frank said, 'That's the house where I was born.' → Frank said ______.","answers":["that was the house where he had been born","that that was the house where he had been born","that was the house where he was born","that that was the house where he was born"],"explanation":"Present simple → past simple (that was), was born → had been born / was born."}$g211$, 11, $g212$rep_statements$g212$),
  ($g213$rep_ex3_7$g213$, $g214$gap$g214$, $g215$elementary$g215$, $g216${"id":"rep_ex3_7","level":"elementary","group":3,"gord":3,"no":7,"instruction":"Turn the following sentences into reported speech.","prompt":"'That was a wonderful party,' said Jill. → Jill said ______.","answers":["that had been a wonderful party","that that had been a wonderful party","that was a wonderful party","that that was a wonderful party","it had been a wonderful party","that it had been a wonderful party","it was a wonderful party","that it was a wonderful party"],"explanation":"Past simple → past perfect: that had been (також лишається was)."}$g216$, 12, $g217$rep_statements$g217$),
