with t as (select id from public.topics where slug = $g1031$reported_speech$g1031$)
insert into public.exercises (topic_id, legacy_id, type, level, payload, position, source, subtopic)
select t.id, v.lid, v.type, v.level, v.payload::jsonb, v.pos, 'book', v.sub from t, (values
  ($g988$rep_ex14_1$g988$, $g989$abcd$g989$, $g990$intermediate$g990$, $g991${"id":"rep_ex14_1","level":"intermediate","group":14,"gord":14,"no":1,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"1. She said that it was going to be a wonderful party. Що вона сказала?","options":["A) 'It was going to be a wonderful party.'","B) 'It's going to be a wonderful party.'","C) 'It will be a wonderful party.'","D) 'It has been going to be a wonderful party.'"],"correct":1,"explanation":"Was going to → is going to. Will дало б would."}$g991$, 0, $g992$rep_mix$g992$),
  ($g993$rep_ex14_2$g993$, $g994$abcd$g994$, $g995$intermediate$g995$, $g996${"id":"rep_ex14_2","level":"intermediate","group":14,"gord":14,"no":2,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"2. He said the bus might be a little late that day. Що він сказав?","options":["A) 'The bus was a little late today.'","B) 'The bus might be a little late today.'","C) 'The bus may have been a little late today.'","D) 'The bus must be a little late today.'"],"correct":1,"explanation":"Might лишається might (або це може бути may); that day → today."}$g996$, 1, $g997$rep_mix$g997$),
  ($g998$rep_ex14_3$g998$, $g999$abcd$g999$, $g1000$intermediate$g1000$, $g1001${"id":"rep_ex14_3","level":"intermediate","group":14,"gord":14,"no":3,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"3. She told him that he should study harder. Що вона сказала?","options":["A) 'You should have studied harder.'","B) 'You should study harder.'","C) 'You must study harder.'","D) 'You would study harder.'"],"correct":1,"explanation":"Should не змінюється; he → you."}$g1001$, 2, $g1002$rep_mix$g1002$),
  ($g1003$rep_ex14_4$g1003$, $g1004$abcd$g1004$, $g1005$intermediate$g1005$, $g1006${"id":"rep_ex14_4","level":"intermediate","group":14,"gord":14,"no":4,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"4. He said that the fire had done a lot of damage to the building. Що він сказав?","options":["A) 'The fire is doing a lot of damage to the building.'","B) 'The fire has done a lot of damage to the building.'","C) 'The fire will do a lot of damage to the building.'","D) 'The fire does a lot of damage to the building.'"],"correct":1,"explanation":"Past perfect (had done) ← present perfect (has done)."}$g1006$, 3, $g1007$rep_mix$g1007$),
  ($g1008$rep_ex14_5$g1008$, $g1009$abcd$g1009$, $g1010$intermediate$g1010$, $g1011${"id":"rep_ex14_5","level":"intermediate","group":14,"gord":14,"no":5,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"5. He said that Michael was the best student he had ever taught. Що він сказав?","options":["A) 'Michael was the best student I have ever taught.'","B) 'Michael is the best student I have ever taught.'","C) 'Michael is the best student I had ever taught.'","D) 'Michael will be the best student I have ever taught.'"],"correct":1,"explanation":"Was → is, had taught → have taught."}$g1011$, 4, $g1012$rep_mix$g1012$),
  ($g1013$rep_ex14_6$g1013$, $g1014$abcd$g1014$, $g1015$intermediate$g1015$, $g1016${"id":"rep_ex14_6","level":"intermediate","group":14,"gord":14,"no":6,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"6. She told us that the new furniture had been delivered the day before. Що вона сказала?","options":["A) 'The new furniture had been delivered yesterday.'","B) 'The new furniture was delivered yesterday.'","C) 'The new furniture has been delivered the day before.'","D) 'The new furniture is delivered yesterday.'"],"correct":1,"explanation":"Had been delivered ← was delivered; the day before ← yesterday."}$g1016$, 5, $g1017$rep_mix$g1017$),
  ($g1018$rep_ex14_7$g1018$, $g1019$abcd$g1019$, $g1020$intermediate$g1020$, $g1021${"id":"rep_ex14_7","level":"intermediate","group":14,"gord":14,"no":7,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"7. They said that the manager would inspect the office the following day. Що вони сказали?","options":["A) 'The manager will inspect the office the following day.'","B) 'The manager will inspect the office tomorrow.'","C) 'The manager would inspect the office tomorrow.'","D) 'The manager inspects the office tomorrow.'"],"correct":1,"explanation":"Would inspect ← will inspect; the following day ← tomorrow."}$g1021$, 6, $g1022$rep_mix$g1022$),
  ($g1023$rep_ex14_8$g1023$, $g1024$abcd$g1024$, $g1025$intermediate$g1025$, $g1026${"id":"rep_ex14_8","level":"intermediate","group":14,"gord":14,"no":8,"instruction":"Choose the correct answer: which sentence is the original direct speech?","q":"8. He said that if we hadn't acted so quickly, the accident would have been even worse. Що він сказав?","options":["A) 'If you haven't acted so quickly, the accident would be even worse.'","B) 'If you hadn't acted so quickly, the accident would have been even worse.'","C) 'If you didn't act so quickly, the accident would have been even worse.'","D) 'If you hadn't acted so quickly, the accident will be even worse.'"],"correct":1,"explanation":"Тип 3 у непрямій мові не змінюється; he → you, we → you."}$g1026$, 7, $g1027$rep_mix$g1027$)
) as v(lid, type, level, payload, pos, sub)
on conflict (legacy_id) where student_id is null do update set
