commit;

-- Контроль: блоки теорії за рівнями та кількість вправ за типами
select 'теорія' as що, tb.level as деталь, count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
  where t.slug = $g1032$reported_speech$g1032$ group by tb.level
union all
select 'вправи', e.type, count(*) from public.exercises e join public.topics t on t.id = e.topic_id
  where t.slug = $g1033$reported_speech$g1033$ and e.student_id is null group by e.type order by 1, 2;

-- Контроль по підтемах: блоки теорії та вправи
select s.sub as підтема, (select count(*) from public.theory_blocks b where b.topic_id = t.id and b.subtopic = s.sub) as теорія,
       (select count(*) from public.exercises e where e.topic_id = t.id and e.subtopic = s.sub and e.student_id is null) as вправи
  from public.topics t cross join lateral jsonb_array_elements(t.subtopics) with ordinality as x(j, ord)
  cross join lateral (select x.j->>'slug' as sub) s where t.slug = $g1034$reported_speech$g1034$ order by x.ord;
